package ru.alfabank.api.accounts.controller;

import io.swagger.v3.oas.annotations.Operation;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.webjars.NotFoundException;
import ru.alfabank.api.accounts.dto.AccountBalance;
import ru.alfabank.api.accounts.dto.BaseAccountInfo;
import ru.alfabank.api.accounts.dto.AccountResponseDto;
import ru.alfabank.api.accounts.dto.BalanceType;
import ru.alfabank.api.accounts.dto.CustomerSetMainAccountRequest;
import ru.alfabank.api.accounts.entity.Account;
import ru.alfabank.api.accounts.entity.AccountingInfo;
import ru.alfabank.api.accounts.entity.CustomerAccountCreationRequest;
import ru.alfabank.api.accounts.entity.CustomerAccountTypes;
import ru.alfabank.api.accounts.service.AccountsService;
import ru.alfabank.ufr.methodslog.Log;
import ru.alfabank.ufr.methodslog.SecurityEventType;

import jakarta.validation.Valid;
import ru.alfabank.ufr.methodslog.annotation.Mask;

import java.util.List;
import java.util.Set;

import static org.springframework.http.MediaType.APPLICATION_JSON_VALUE;
import static ru.alfabank.ufr.methodslog.MaskType.ACCOUNT_NUMBER;
import static ru.alfabank.ufr.methodslog.MaskType.CRITICAL;

@RestController
class AccountsAPIController {
    private final AccountsService accountsService;

    @Autowired
    public AccountsAPIController(AccountsService accountsService) {
        this.accountsService = accountsService;
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Получение списка счетов клиента с фильтрацией по переданным параметрам")
    @GetMapping(value = "/accounts/{pinEq}", produces = APPLICATION_JSON_VALUE)
    public ResponseEntity<Set<Account>> getAccountListByPinEq(@PathVariable("pinEq") String pinEq,
                                                              @RequestParam(value = "act", required = false) String[] act,
                                                              @RequestParam(value = "operationTypes", required = false) String[] operationTypes,
                                                              @RequestParam(value = "includeCurrencies", required = false) String[] includeCurrencies,
                                                              @RequestParam(value = "excludeCurrencies", required = false) String[] excludeCurrencies,
                                                              @RequestParam(value = "getBranchInfo", required = false) boolean getBranchInfo,
                                                              @RequestParam(value = "ignoreAccountingMode", required = false) boolean ignoreAccountingMode,
                                                              @RequestParam(value = "getLastTransactionDate", required = false) boolean getLastTransactionDate,
                                                              @RequestParam(required = false, defaultValue = "false") boolean getBalanceGovernment,
                                                              @RequestParam(required = false, defaultValue = "true") boolean useNewBalance,
                                                              @RequestParam(value = "accountNumbers", required = false) @Mask(CRITICAL) String[] accountNumbers,
                                                              @RequestParam(value = "includeAccountsWithSpecificTypes", required = false, defaultValue = "false") boolean includeAccountsWithSpecificTypes,
                                                              @RequestParam(required = false, defaultValue = "false") boolean getComboInfo) {
        Set<Account> accountList = accountsService.getAccountListByParams(pinEq, act, operationTypes, includeCurrencies,
                excludeCurrencies, getBranchInfo, ignoreAccountingMode, getLastTransactionDate, getBalanceGovernment,
                useNewBalance, accountNumbers, includeAccountsWithSpecificTypes, getComboInfo);
        return ResponseEntity.ok(accountList);
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Получение информации по счету")
    @GetMapping(value = "/account/{accountNumber}", produces = APPLICATION_JSON_VALUE)
    public ResponseEntity<Account> getAccountByNumber(@PathVariable("accountNumber") @Mask(ACCOUNT_NUMBER) String accountNumber) {

        Account account = accountsService.getAccountByNumber(accountNumber);
        return new ResponseEntity<>(account, HttpStatus.OK);
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Получение расширенной информации по счету")
    @GetMapping(value = "/account-details/{accountNumber}", produces = APPLICATION_JSON_VALUE)
    public ResponseEntity<BaseAccountInfo> getAccountDetailsByNumber(
            @PathVariable("accountNumber")
            @Mask(ACCOUNT_NUMBER)
            String accountNumber) {
        try {
            BaseAccountInfo baseAccountInfo = accountsService.getBaseAccountInfoByNumber(accountNumber);
            return new ResponseEntity<>(baseAccountInfo, HttpStatus.OK);
        } catch (NotFoundException e) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        } catch (RuntimeException e) {
            return new ResponseEntity<>(HttpStatus.BAD_GATEWAY);
        }
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Возвращает список типов счетов с валютами")
    @GetMapping(value = "/accountTypes", produces = APPLICATION_JSON_VALUE)
    public ResponseEntity<CustomerAccountTypes> getCustomerAccountTypes(@RequestParam("cus") String cus,
                                                                        @RequestParam("useRestrictions") boolean useRestrictions,
                                                                        @RequestParam(value = "filterBankruptAccount", defaultValue = "true") boolean filterBankruptAccount) {

        CustomerAccountTypes customerAccountTypes = accountsService.getCustomerAccountTypes(cus, useRestrictions, filterBankruptAccount);
        return new ResponseEntity<>(customerAccountTypes, HttpStatus.OK);
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Открытие нового счёта")
    @PostMapping(value = "/accounts", produces = APPLICATION_JSON_VALUE)
    public ResponseEntity<AccountResponseDto> createCustomerAccount(@Valid @RequestBody CustomerAccountCreationRequest request) {

        AccountResponseDto accountResponseDto = accountsService.createCustomerAccount(request);
        return new ResponseEntity<>(accountResponseDto, HttpStatus.OK);
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Возвращает информацию о текущем балансе по счету и дате последней транзакции")
    @GetMapping(value = "/accounts/{accountNumber}/accounting-info", produces = APPLICATION_JSON_VALUE)
    public ResponseEntity<AccountingInfo> getAccountingInfo(@PathVariable("accountNumber") @Mask(ACCOUNT_NUMBER) String accountNumber) {

        final AccountingInfo accountingEntriesInfo = accountsService
                .getAccountingInfo(accountNumber);
        return new ResponseEntity<>(accountingEntriesInfo, HttpStatus.OK);
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Получение остатков по счетам")
    @GetMapping(value = "/account-balance", produces = APPLICATION_JSON_VALUE)
    public ResponseEntity<List<AccountBalance>> getAccountBalance(@RequestParam(value = "account-numbers") @Mask(CRITICAL) Set<String> accountNumberList,
                                                                  @RequestParam(value = "balance-types") Set<BalanceType> balanceTypesList) {

        final List<AccountBalance> accountBalanceList = accountsService.getSpecialAccountBalance(accountNumberList, balanceTypesList);
        return accountBalanceList.isEmpty() ? new ResponseEntity<>(HttpStatus.NOT_FOUND) : new ResponseEntity<>(accountBalanceList, HttpStatus.OK);
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Установка признака основного счета")
    @PostMapping(value = "/accounts/{accountNumber}/main", produces = APPLICATION_JSON_VALUE)
    public ResponseEntity<Void> setMainAccount(@PathVariable @Mask(ACCOUNT_NUMBER) String accountNumber, @Valid @RequestBody CustomerSetMainAccountRequest request) {

        accountsService.setMainAccount(accountNumber, request.getCus(), request.getAccountSuffix(), request.getBranchId());

        return new ResponseEntity<>(HttpStatus.OK);
    }

    @Log(securityAudit = true, securityEventType = SecurityEventType.BUSINESS_OPERATION)
    @Operation(summary = "Метод обновления имени клиента для счетов")
    @PatchMapping(value = "/accounts/{pinEq}", produces = APPLICATION_JSON_VALUE)
    public void changeAccountName(@PathVariable("pinEq") String pinEq) {
        accountsService.changeAccountName(pinEq);
    }
}
```

